import * as T from './vendor/three.module.js';
export function buildExtraObject({c,model,add,box,rounded,physical,paper,dark,frontTex,images}){
 const owned=(ca)=>{const t=new T.CanvasTexture(ca);t.colorSpace=T.SRGBColorSpace;const m=physical({map:t,roughness:.8});m.userData.ownedMap=t;return m};
 const page=(text,image)=>{const ca=Object.assign(document.createElement('canvas'),{width:768,height:1024}),x=ca.getContext('2d');x.fillStyle='#eee7d7';x.fillRect(0,0,768,1024);x.fillStyle='#393a34';x.font='18px serif';let yy=100;if(image){x.drawImage(image,60,80,648,440);yy=580}for(const paragraph of String(text||'在这里写下这一页的内容。').split('\n')){let line='';for(const ch of paragraph){if(x.measureText(line+ch).width>620){x.fillText(line,74,yy);yy+=32;line=ch}else line+=ch;}x.fillText(line,74,yy);yy+=42;if(yy>960)break;}x.font='14px serif';x.textAlign='center';x.fillText('PRIVATE LIBRARY / AFTERIMAGE',384,980);return ca};
 if(c.kind==='book'){const cloth=physical({color:'#36494b',roughness:.95,bumpMap:null});box(2.24,3.04,.08,cloth,[0,0,-.23]);box(2.12,2.92,.34,paper,[0,0,-.02]);for(let i=0;i<24;i++)box(2.1,.004,.34,physical({color:i%2?'#d5cbb7':'#e7dfcb',roughness:1}),[0,-1.4+i*.118,-.01]);box(.14,3.03,.46,cloth,[-1.12,0,-.015]);const right=owned(page(c.pageRight,images.pageRight));add(new T.PlaneGeometry(2.08,2.88),right,model,[0,0,.16]);const hinge=new T.Group();hinge.position.set(-1.1,0,.19);model.add(hinge);box(2.25,3.04,.07,cloth,[1.1,0,0],hinge);add(new T.PlaneGeometry(2.12,2.91),physical({map:frontTex,roughness:.86}),hinge,[1.1,0,.04]);const left=add(new T.PlaneGeometry(2.08,2.88),owned(page(c.pageLeft,images.pageLeft)),hinge,[1.1,0,-.04]);left.rotation.y=Math.PI;hinge.rotation.y=-c.opening*Math.PI/180;return {hinge};}
 if(c.kind==='player'||c.kind==='xp'){
 const player=c.kind==='player',W=player?2:3.2,H=player?3.2:2.3;const bodyMat=physical({color:player?'#d5d9d7':'#303c47',metalness:player?.55:.12,roughness:.38});if(rounded)add(rounded(W,H,.22,.12),bodyMat,model);else box(W,H,.22,bodyMat,[0,0,0]);box(W-.14,player?1.72:H-.2,.035,dark,[0,player?.54:0,.13]);const ca=Object.assign(document.createElement('canvas'),{width:900,height:player?770:600}),x=ca.getContext('2d');const texture=new T.CanvasTexture(ca);texture.colorSpace=T.SRGBColorSpace;const material=physical({map:texture,emissiveMap:texture,emissive:'#ffffff',emissiveIntensity:.22,roughness:.13,clearcoat:1});material.userData.ownedMap=texture;
 const screen=add(new T.PlaneGeometry(W-.24,player?1.62:H-.3),material,model,[0,player?.54:0,.16]);
 const refresh=()=>{x.fillStyle=player?'#c8d5c7':'#3888a9';x.fillRect(0,0,900,ca.height);if(player){x.fillStyle='#223a30';x.font='32px monospace';x.fillText('NOW PLAYING                    ▰',30,52);if(frontTex?.image)x.drawImage(frontTex.image,32,95,340,400);x.font='36px sans-serif';x.fillText((c.title||'Untitled').slice(0,22),400,180,470);x.font='24px sans-serif';x.fillText(c.subtitle||'Local collection',400,235,470);x.fillText(c.audioPlaying?'Ⅱ PLAYING':'▷ PAUSED',400,335);x.fillRect(40,620,820,3);x.fillRect(40,603,820*(c.playhead||0),22);x.font='25px monospace';x.fillText('AFTERIMAGE / PORTABLE',40,710);}else{if(frontTex?.image)x.drawImage(frontTex.image,0,0,900,600);x.fillStyle='#2364bd';x.fillRect(0,555,900,45);x.fillStyle='#45914a';x.fillRect(0,555,145,45);x.fillStyle='#fff';x.font='23px sans-serif';x.fillText('start',25,586);x.fillStyle='#397bc7';x.fillRect(155,559,230,36);x.fillStyle='#ffffff';x.fillText('My Pictures',170,585);if(c.windowClosed){texture.needsUpdate=true;return;}const wx=Math.round(c.windowX*900),wy=Math.round(c.windowY*600);x.fillStyle='#124bb7';x.fillRect(wx-5,wy-5,545,365);x.fillStyle='#eeeede';x.fillRect(wx,wy+42,535,312);const g=x.createLinearGradient(0,wy,0,wy+42);g.addColorStop(0,'#6e9bec');g.addColorStop(.5,'#1553c5');g.addColorStop(1,'#3f7cdd');x.fillStyle=g;x.fillRect(wx,wy,535,42);x.fillStyle='#fff';x.font='21px sans-serif';x.fillText(c.title||'My Pictures',wx+14,wy+29,430);x.fillStyle='#c95d43';x.fillRect(wx+495,wy+6,30,29);x.fillStyle='#fff';x.fillText('×',wx+501,wy+28);x.fillStyle='#343938';x.font='22px sans-serif';x.fillText(c.subtitle||'A little room for your memories.',wx+24,wy+96,490);if(frontTex?.image)x.drawImage(frontTex.image,wx+24,wy+125,310,200);}texture.needsUpdate=true;};refresh();
 if(player){const ring=add(new T.RingGeometry(.25,.64,64),physical({color:'#eff0e9',roughness:.6}),model,[0,-.88,.15]);add(new T.CircleGeometry(.24,48),physical({color:'#c8ccc8',metalness:.3,roughness:.4}),model,[0,-.88,.155]);for(const pos of [[0,-.38],[.48,-.88],[-.48,-.88],[0,-1.38]])box(.035,.035,.01,dark,[pos[0],pos[1],.17]);}else{box(1.3,.13,.6,dark,[0,-1.3,-.1]);}
 return {screen,refresh};
 }
 return {};
}
